        # Cluster 6: car rental pickup
        ('Ms Lan', "I have a reservation to pick up a rental car this afternoon, could you help me with that now?", "Chiều nay tôi có đặt thuê xe, anh giúp tôi làm thủ tục bây giờ được không ạ?"),
        ('Mr Dovecote', "Of course, may I see your license and the confirmation number, and we'll get you into that car quickly.", "Được chứ, cho tôi xem bằng lái và mã xác nhận, mình sẽ làm nhanh để chị nhận xe."),
        ('Ms Lan', "Here you go, I printed the confirmation email out just in case the app wasn't working today.", "Đây ạ, tôi đã in email xác nhận ra phòng khi ứng dụng hôm nay không hoạt động."),
        ('Ms Lan', "Does the rental price include insurance, or should I add that separately before I drive it away?", "Giá thuê xe có bao gồm bảo hiểm không ạ, hay tôi phải thêm riêng trước khi lái đi?"),
